const beatPattern = (length, hits) => {
  hits = Math.min(length,hits);
	const a = new Array(length).fill(0);
  	while(Math.floor(hits)>0) {
      const r = Math.floor(Math.random()*length);
      if (a[r]) {
        continue;
      } else {
      	a[r] = 1;
      	hits--;
      }
    }
  	return a;
}

